type Company={id:string;name:string;description:string;contact?:{name:string;email:string}|null};
type Task={level:string;requirements:string;id:string;companyId:string;universityId:string;title:string;description:string;criteria:string;rewardKopecks:number;hours:number;deadline:string;profiled:boolean;skill:string;state:string};
type Profile={approvedSkills?:{skill:string;basis:string}[];name?:string;id:string;studentId:string;headline:string;about:string;skills:string[];verification:string};
type Work={id:string;taskId:string;studentId:string;state:string;submission:string;resultUrl:string;decisionReason:string};
type Application={id:string;taskId:string;studentId:string;message:string;state:string};
type Review={id:string;workId:string;rating:number;body:string;publishAllowed:boolean};
type Data={availableModes:string[];notices:{id:string;title:string;body:string;isRead:boolean;createdAt:string}[];actor:{id:string;role:string};mode:string;payment:{configured:boolean};limit:number;companies:Company[];partnerships:{id:string;companyId:string;universityId:string;state:string}[];profile:Profile|null;profiles:Profile[];candidates:Profile[];admissions:{id:string;studentId:string;skill:string;evidence:string;state:string;reason:string}[];memberships:{id:string;role:string;companyId:string|null}[];tasks:Task[];works:Work[];applications:Application[];reviews:Review[];portfolio:{id:string;workId:string;published:boolean;caseText:string}[];universities:{id:string;name:string}[];staff:{id:string;firstName:string;lastName:string;role:string}[]};
type Page<T>={items:T[];total:number;offset:number;limit:number;hasMore:boolean};
type CareerTestRow={id:string;title:string;skill:string;passingPercent:number;remainingAttempts?:number;questions:{prompt:string;options:string[]}[]};
type StudentAdmission={id:string;skill:string;evidence:string;state:string;reason:string;createdAt:string};
type StudentAdmissionsPage=Page<StudentAdmission>&{approvedSkills:string[]};
type NoticeRow=Data['notices'][number];
type TaskRow=Task;
type WorkflowRow=(Application|Work)&{task:Task|null;company:string;candidate?:{studentId:string;name:string;headline:string;skills:string[];approvedSkills:{skill:string;basis:string}[]}|null;review?:Review|null};
type CenterReviewRow=(Profile|Data['admissions'][number])&{studentName:string};
type PartnershipRow=Data['partnerships'][number]&{companyName:string;universityName:string};
type Field={key:string;label:string;type?:string;value?:string|number|boolean;options?:{value:string;label:string}[];optional?:boolean};
const labels:Record<string,string>={not_selected:'Выбран другой исполнитель',pending:'На проверке',verified:'Подтверждён',rejected:'Отклонён',approved:'Допуск выдан',draft:'Черновик',review:'Модерация',open:'Открыта',assigned:'Исполнитель выбран',in_progress:'В работе',submitted:'На приёмке',revision:'На доработке',accepted:'Работа принята',selected:'Выбран'};
const rubles=(n:number)=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(n/100);

function Form({fields,label,onSubmit,busy,convert,suggestion,renderField}:{fields:Field[];label:string;onSubmit:(value:Record<string,unknown>)=>Promise<unknown>;busy:boolean;convert?:(value:Record<string,unknown>)=>Record<string,unknown>;suggestion?:TaskSuggestion|null;renderField?:(field:Field)=>ReactNode|null}){
  const formRef=useRef<HTMLFormElement>(null);useEffect(()=>{if(suggestion)for(const key of ['title','description','criteria'] as const){const input=formRef.current?.elements.namedItem(key);if(input instanceof HTMLInputElement||input instanceof HTMLTextAreaElement)input.value=suggestion[key];}},[suggestion]);
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const payload:Record<string,unknown>={};for(const field of fields)payload[field.key]=field.type==='checkbox'?form.get(field.key)==='on':field.type==='number'?Number(form.get(field.key)):String(form.get(field.key)||'').trim();await onSubmit(convert?convert(payload):payload);}
  return <form ref={formRef} className={s.form} onSubmit={event=>void submit(event)}><fieldset disabled={busy} style={{border:0,padding:0,margin:0}}><div className={s.fields}>{fields.map(field=>{const customField=renderField?.(field);if(customField)return customField;if(field.type==='skills')return <SkillInput key={field.key} name={field.key} label={field.label} initialValue={String(field.value||'')}/>;return <label key={field.key} className={`${s.field} ${field.type==='textarea'?s.wide:''}`}>{field.label}{field.options?<select name={field.key} defaultValue={String(field.value||'')} required={!field.optional}><option value="">Выберите</option>{field.options.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select>:field.type==='textarea'?<textarea name={field.key} defaultValue={String(field.value||'')} required={!field.optional} maxLength={10000}/>:<input name={field.key} type={field.type||'text'} defaultValue={field.type==='checkbox'?undefined:String(field.value||'')} defaultChecked={field.type==='checkbox'?Boolean(field.value):undefined} required={field.type==='checkbox'?false:!field.optional} maxLength={field.type==='password'?128:2000} min={field.type==='number'?1:undefined} step={field.type==='number'?(field.key==='reward'?'0.01':'1'):undefined}/>}</label>})}</div></fieldset><button type="submit" disabled={busy} className={`${s.button} ${s.primary}`}>{busy?'Сохраняем…':label}</button></form>;
}

function CareerTestComposer({busy,onSubmit}:{busy:boolean;onSubmit:(value:Record<string,unknown>)=>Promise<unknown>}){
  const [optionCounts,setOptionCounts]=useState([0,0,0]);const [answers,setAnswers]=useState(['','','']);const [error,setError]=useState('');
  async function submit(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const questions=[1,2,3].map(n=>{const options=String(form.get(`o${n}`)||'').split(/\r?\n/).map(value=>value.trim()).filter(Boolean);return {prompt:String(form.get(`q${n}`)||'').trim(),options,answer:Number(form.get(`a${n}`))};});
    const invalidQuestion=questions.findIndex((question,index)=>{const rawAnswer=String(form.get(`a${index+1}`)||'');return question.options.length<2||question.options.length>6||question.options.some(option=>option.length>500)||new Set(question.options).size!==question.options.length||rawAnswer===''||question.answer>=question.options.length;});
    if(invalidQuestion!==-1){setError(`Проверьте вопрос ${invalidQuestion+1}: добавьте 2–6 разных вариантов и выберите существующий правильный ответ.`);return;}
    setError('');await onSubmit({title:String(form.get('title')||'').trim(),skill:String(form.get('skill')||'').trim(),passingPercent:Number(form.get('passingPercent')),questions});
  }
  function updateOptions(index:number,value:string){const count=value.split(/\r?\n/).map(option=>option.trim()).filter(Boolean).length;setOptionCounts(current=>current.map((item,i)=>i===index?count:item));setAnswers(current=>current.map((answer,i)=>i===index&&answer!==''&&Number(answer)>=count?'':answer));setError('');}
  return <form className={s.form} onSubmit={event=>void submit(event)}><fieldset disabled={busy} style={{border:0,padding:0,margin:0}}><div className={s.fields}>
    <label className={s.field}>Название теста<input name="title" required minLength={5} maxLength={180}/></label>
    <label className={s.field}>Направление<input name="skill" required minLength={2} maxLength={80}/></label>
    <label className={s.field}>Проходной процент<input name="passingPercent" type="number" required min={1} max={100} step={1} defaultValue={70}/></label>
    {[1,2,3].map(n=>{const index=n-1;return <div className={s.wide} key={n}>
      <label className={s.field}>Вопрос {n}<textarea name={`q${n}`} required minLength={10} maxLength={2000}/></label>
      <label className={s.field}>Варианты ответа, каждый с новой строки<textarea name={`o${n}`} required maxLength={3200} onChange={event=>updateOptions(index,event.target.value)}/></label>
      <label className={s.field}>Номер правильного варианта<select name={`a${n}`} value={answers[index]} required disabled={optionCounts[index]<2} onChange={event=>{setAnswers(current=>current.map((answer,i)=>i===index?event.target.value:answer));setError('');}}><option value="">Выберите вариант</option>{Array.from({length:Math.min(optionCounts[index],6)},(_,i)=><option key={i} value={String(i)}>{i+1}</option>)}</select></label>
      <p className={s.muted}>Добавьте от 2 до 6 вариантов. Список правильных ответов обновляется при вводе.</p>
    </div>;})}
  </div></fieldset>{error&&<p role="alert" className={s.error}>{error}</p>}<button type="submit" disabled={busy} className={`${s.button} ${s.primary}`}>{busy?'Сохраняем…':'Опубликовать тест'}</button></form>;
}

