  const [centerPage,setCenterPage]=useState<Page<CenterReviewRow>|null>(null);const [centerLoading,setCenterLoading]=useState(false);const [centerError,setCenterError]=useState('');const [centerQuery,setCenterQuery]=useState('');const [centerKind,setCenterKind]=useState<'profiles'|'admissions'>('profiles');const [centerState,setCenterState]=useState('pending');const [centerRefresh,setCenterRefresh]=useState(0);const centerRequest=useRef(0);
  const [partnershipPage,setPartnershipPage]=useState<Page<PartnershipRow>|null>(null);const [partnershipLoading,setPartnershipLoading]=useState(false);const [partnershipError,setPartnershipError]=useState('');const [partnershipQuery,setPartnershipQuery]=useState('');const [partnershipState,setPartnershipState]=useState('pending');const [partnershipRefresh,setPartnershipRefresh]=useState(0);const partnershipRequest=useRef(0);
  const [noticePage,setNoticePage]=useState<Page<NoticeRow>|null>(null);const [noticeLoading,setNoticeLoading]=useState(false);const [noticeError,setNoticeError]=useState('');const noticeRequest=useRef(0);const [unreadCount,setUnreadCount]=useState<number|null>(null);const [unreadCountLoading,setUnreadCountLoading]=useState(false);const [unreadCountError,setUnreadCountError]=useState('');const [unreadCountRefresh,setUnreadCountRefresh]=useState(0);const unreadCountRequest=useRef(0);
  const [studentAdmissions,setStudentAdmissions]=useState<StudentAdmissionsPage|null>(null);const [studentAdmissionsLoading,setStudentAdmissionsLoading]=useState(false);const [studentAdmissionsError,setStudentAdmissionsError]=useState('');const [studentAdmissionsRefresh,setStudentAdmissionsRefresh]=useState(0);const studentAdmissionsRequest=useRef(0);
