  const fetchNotices=useCallback(async(offset:number,append:boolean)=>{const request=++noticeRequest.current;setNoticeLoading(true);setNoticeError('');try{const query=new URLSearchParams({offset:String(offset),limit:'20'});const result=await careerApi<Page<NoticeRow>>(`/career/notices?${query}`);if(request===noticeRequest.current)setNoticePage(old=>append&&old?{...result,items:[...old.items,...result.items]}:result);}catch(reason){if(request===noticeRequest.current)setNoticeError(reason instanceof Error?reason.message:'Не удалось загрузить уведомления');}finally{if(request===noticeRequest.current)setNoticeLoading(false);}},[]);
