  const fetchStudentAdmissions=useCallback(async(offset:number,append:boolean)=>{const request=++studentAdmissionsRequest.current;setStudentAdmissionsLoading(true);setStudentAdmissionsError('');try{const query=new URLSearchParams({offset:String(offset),limit:'20'});const result=await careerApi<StudentAdmissionsPage>(`/career/student/admissions?${query}`);if(request===studentAdmissionsRequest.current)setStudentAdmissions(old=>append&&old?{...result,items:[...old.items,...result.items]}:result);}catch(reason){if(request===studentAdmissionsRequest.current)setStudentAdmissionsError(reason instanceof Error?reason.message:'Не удалось загрузить допуски');}finally{if(request===studentAdmissionsRequest.current)setStudentAdmissionsLoading(false);}},[]);
